-- Шаблони відповідей покупцям (адмінка → «Повідомлення»). Редагуються в адмінці.
-- Плейсхолдери в тексті: {hi} {name} {code} {email} — дані клієнта; {card} {owner} {paylink} {sign} — реквізити (admin_settings);
-- {price} {price_note} {link} {app} {mail} {howto} {wish} {follow} — підставляє адмінка.
CREATE TABLE reply_templates (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  section    TEXT NOT NULL,
  title      TEXT NOT NULL,
  channel    TEXT NOT NULL DEFAULT 'msg',   -- msg (Messenger) | mail (лист) | com (коментар)
  hint       TEXT NOT NULL DEFAULT '',      -- коли надсилати
  note       TEXT NOT NULL DEFAULT '',      -- застереження для себе
  subject    TEXT NOT NULL DEFAULT '',      -- тема листа
  body       TEXT NOT NULL DEFAULT '',
  show_until INTEGER,                       -- після цієї миті шаблон ховається (NULL — завжди)
  sort       INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);

-- Дрібні налаштування адмінки (реквізити для шаблонів тощо)
CREATE TABLE admin_settings (
  k TEXT PRIMARY KEY,
  v TEXT NOT NULL DEFAULT ''
);

INSERT INTO reply_templates (section, title, channel, hint, note, subject, body, show_until, sort, created_at, updated_at) VALUES
('Перші відповіді', 'Привітання з реклами', 'msg', 'Автоматичне привітання в шаблоні оголошення.', '', '', 'Вітаю! 😊 Це «Дивоурок». Оберіть питання нижче або просто напишіть, що вас цікавить.', NULL, 10, 1791842681289, 1791842681289),
('Перші відповіді', 'Автоматичні питання в рекламі', 'msg', 'Варіанти кнопок під автоматичним привітанням.', '', '', 'Хочу замовити за {price}
Що входить у набір?
Чи підійде моєму класу?
Подивитися демо', NULL, 20, 1791842681289, 1791842681289),
('Перші відповіді', 'Відповідь на перший відгук', 'msg', 'Людина відгукнулась на рекламу чи пост. Коротко й з одним простим питанням.', '', '', 'Вітаю! 😊 «Машина часу рідної мови» — готовий урок до 27 жовтня для 1–11 класів: 5 мультфільмів, інтерактивний квест, роздатка, грамоти та сценарій на 45 хвилин.

Увесь набір коштує {price}, доступ залишається назавжди.{price_note}

Для якого класу вам потрібно?', NULL, 30, 1791842681289, 1791842681289),
('Перші відповіді', 'Хочу демо', 'msg', 'Людина просить подивитися.', '', '', 'Ось демо 🙂 Натисніть «Спробувати безкоштовно», оберіть свій клас — і можна пройти цілу зупинку «Тарас Шевченко»: мультфільм і завдання, як на дошці. Там само видно сторінки роздатки.
{link}', NULL, 40, 1791842681289, 1791842681289),
('Перші відповіді', 'Скільки коштує?', 'msg', 'Питання про ціну.', '', '', 'Увесь набір коштує {price}. У ньому вже є версії для 1–4, 5–7 і 8–11 класів, доступ назавжди та робота на 3 пристроях.{price_note}

Оформлюємо? Напишіть «ОФОРМИТИ», і я одразу надішлю реквізити 🙂', NULL, 50, 1791842681289, 1791842681289),
('Перші відповіді', 'Для якого класу?', 'msg', 'Питання про клас.', '', '', 'Для 1–11 класів 🙂 У застосунку ви обираєте рівень: 1–4, 5–7 або 8–11. Герої й мультфільми ті самі, а завдання, сценарій і роздатка адаптовані до віку. Для старших є робота з першоджерелами, питання та есе.

Для якого класу вам потрібно?', NULL, 60, 1791842681289, 1791842681289),
('Перші відповіді', 'Чи можна для одного класу?', 'msg', '«Для одного класу не можна замовити?» — людина думає, що платить за всі класи.', '', '', 'Так, можна 🙂 Ви обираєте потрібну версію для свого класу. Водночас за {price} отримуєте весь набір із рівнями 1–4, 5–7 і 8–11, окремо доплачувати за інші класи не потрібно.

Для якого класу вам потрібно? Підкажу, які там завдання 💛', NULL, 70, 1791842681289, 1791842681289),
('Перші відповіді', 'Людина назвала клас', 'msg', 'Після відповіді «мені для 11 класу» або іншого конкретного класу.', '', '', 'Чудово 😊 Для вашого класу є окрема адаптована версія із завданнями відповідного рівня. Увесь набір коштує {price}, доступ залишається назавжди.{price_note}

Оформлюємо? Якщо так, одразу надішлю реквізити 💛', NULL, 80, 1791842681289, 1791842681289),
('Перші відповіді', 'Що входить у набір?', 'msg', 'Людина хоче деталей.', '', '', 'У наборі «Машина часу рідної мови»:
✔ квест для дошки чи проєктора: 5 епох — Кирило і Мефодій, Нестор, Шевченко, Леся Українка, Франко; за кожне завдання клас отримує букву, а разом букви відкривають скриню з дипломом;
✔ 5 мультфільмів, де класики самі розповідають про себе;
✔ роздатка для друку (PDF) і грамоти;
✔ сценарій уроку на 45 хвилин і відповіді для вчителя;
✔ три рівні: 1–4, 5–7 і 8–11 клас.
Усі факти перевірені за джерелами, список є в застосунку.

Оформлюємо набір за {price}? Якщо так, одразу надішлю реквізити 🙂', NULL, 90, 1791842681289, 1791842681289),
('Перші відповіді', 'Питали про старші класи раніше', 'msg', 'Тим, кому бот відповів «лише для 1–4».', '', '', 'Вітаю! 🙂 Ви питали про старші класи. Тепер «Машина часу рідної мови» є і для 5–7, і для 8–11 класів.

Для старших є робота з першоджерелами: Шевченко, Леся Українка та Франко, окрема роздатка з питаннями й есе, сценарій і відповіді для вчителя.

Увесь набір коштує {price}, доступ назавжди.{price_note} Оформлюємо?', NULL, 100, 1791842681289, 1791842681289),
('Оплата', 'Оплата за посиланням', 'msg', 'Людина каже «хочу купити» — найшвидший спосіб.', '', '', 'Чудово! 💛 Оплатити можна карткою будь-якого банку або через Google Pay:
{paylink}

1. Введіть суму {price}.
2. Натисніть «Додати коментар» і напишіть своє ім''я та прізвище.
3. Оплатіть.

Після оплати напишіть сюди, будь ласка, вашу пошту — і я одразу надішлю код доступу. Скриншот не потрібен 🙂', NULL, 110, 1791842681289, 1791842681289),
('Оплата', 'Реквізити для оплати', 'msg', 'Якщо посилання не спрацювало — оплата переказом на картку.', '', '', 'Чудово! 💛 Оплатити можна переказом {price} на картку:
{card}
Отримувач: {owner}

Після оплати надішліть, будь ласка, скриншот квитанції, ваше ім''я та прізвище (на них оформимо код доступу) і пошту — і ми одразу надішлемо код.', NULL, 120, 1791842681289, 1791842681289),
('Оплата', 'Оплата є, а даних немає', 'msg', 'Прийшла лише квитанція.', '', '', '{hi}, дякуємо! Оплату отримали 💛
Щоб надіслати вам код доступу, напишіть, будь ласка:
1. ваше ім''я та прізвище (на них оформимо код доступу);
2. електронну пошту, на яку надіслати код та інструкцію.

Код відкриває весь набір для 1–4, 5–7 і 8–11 класів. Його можна активувати на трьох пристроях: дошці, ноутбуці й телефоні.', NULL, 130, 1791842681289, 1791842681289),
('Оплата', 'Оплата ще не надійшла', 'msg', 'Квитанція є, а гроші ще не видно.', '', '', '{hi}, дякую за квитанцію! Поки що переказ не відображається. Я перевірю надходження й одразу напишу вам, щойно воно з''явиться 🙂', NULL, 140, 1791842681289, 1791842681289),
('Оплата', 'Коли отримаю доступ? Урок уже завтра', 'msg', 'Людині терміново потрібні матеріали.', '', '', 'Після підтвердження оплати я надішлю код доступу та коротку інструкцію сюди й на вашу електронну пошту. Підготовка не потрібна: сценарій, матеріали та відповіді вже всередині.

Оформлюємо? Якщо так, одразу надішлю реквізити 🙂', NULL, 150, 1791842681289, 1791842681289),
('Видача коду', 'Код у Messenger', 'msg', 'Основний спосіб: доходить одразу.', '', '', '{hi}, дякую! Оплату отримано 💛 Ось ваш код доступу: {code}

{howto}

Код та інструкцію дублюємо на пошту {email}.

{wish}', NULL, 160, 1791842681289, 1791842681289),
('Видача коду', 'Лист із кодом', 'mail', 'Дублюємо код на пошту.', '', 'Ваш код доступу до «Машини часу рідної мови»', '{hi}!

Дякуємо за покупку в «Дивоуроці» 💛

Ваш код доступу: {code}

Як почати:
{howto}

Код працює на 3 пристроях (наприклад, дошка, ноутбук і телефон). Щоб перенести доступ на інший пристрій, на старому натисніть іконку людини вгорі → «Вийти з цього пристрою».

Роздатку для друку (PDF) і сценарій уроку знайдете в наборі: розділи «Роздатка» та «Для вчителя».

{wish}

{sign}', NULL, 170, 1791842681289, 1791842681289),
('Видача коду', 'Запросити підписатися', 'msg', 'Окремим повідомленням тим, хто вже купив або довго спілкувався.', '', '', '{hi}, дякуємо, що ви з нами! 💛 {follow}', NULL, 180, 1791842681289, 1791842681289),
('Видача коду', 'Уточнити ім''я покупця', 'msg', 'Ім''я в Messenger російською або нікнеймом.', '', '', '{hi}, підкажіть, будь ласка, як правильно написати ваше ім''я та прізвище українською — на них оформлюємо код доступу 🙂', NULL, 190, 1791842681289, 1791842681289),
('Часті питання', 'Що отримаю після оплати?', 'msg', 'Людина хоче зрозуміти, у якому вигляді надійдуть матеріали.', '', '', 'Після оплати ви отримаєте особистий код доступу до всього набору: інтерактивного квесту, 5 мультфільмів, роздатки, грамот, сценарію та відповідей. Код працює на 3 пристроях, доступ залишається назавжди.', NULL, 200, 1791842681289, 1791842681289),
('Часті питання', 'Це файл чи сайт?', 'msg', 'Людина уточнює формат матеріалів.', '', '', 'Основна частина відкривається у браузері за кодом доступу, нічого встановлювати не потрібно. Роздатку, грамоти та сценарій можна завантажити у PDF і роздрукувати. Також набір можна заздалегідь зберегти для роботи без інтернету.', NULL, 210, 1791842681289, 1791842681289),
('Часті питання', 'Без інтерактивної дошки', 'msg', '«У мене немає дошки».', '', '', 'Дошка не обов''язкова 🙂 Усе працює на ноутбуці з проєктором, на звичайному телевізорі чи навіть на ноутбуці, якщо клас невеликий. Завдання можна виконувати мишкою, а діти підказують відповіді.', NULL, 220, 1791842681289, 1791842681289),
('Часті питання', 'Без інтернету', 'msg', '«У школі поганий інтернет».', '', '', 'Так, працює без інтернету 🙂 Один раз, удома, відкрийте набір і натисніть «Робота без інтернету → Зберегти» (≈100 МБ). Після цього мультфільми, завдання й роздатка відкриються навіть без мережі на цьому пристрої.', NULL, 230, 1791842681289, 1791842681289),
('Часті питання', 'Скільки пристроїв', 'msg', '«Можна на дошці і вдома?»', '', '', 'Так 🙂 Один код працює на 3 пристроях одночасно: наприклад, дошка в класі, ноутбук і телефон. Щоб перенести доступ на новий пристрій, на старому натисніть іконку людини вгорі → «Вийти з цього пристрою».', NULL, 240, 1791842681289, 1791842681289),
('Часті питання', 'Дистанційний урок', 'msg', '«У нас онлайн-навчання».', '', '', 'Підходить і для дистанційки 🙂 Покажіть екран у Meet чи Zoom: мультфільми йдуть зі звуком, а учні диктують відповіді, і ви натискаєте їх у завданнях. Роздатку можна надіслати як PDF.', NULL, 250, 1791842681289, 1791842681289),
('Часті питання', 'Скільки триває урок', 'msg', '«На скільки часу?»', '', '', 'Урок розрахований на 45 хвилин, сценарій із хронометражем є в розділі «Для вчителя». Кожна зупинка працює окремо, тож можна проходити по одній протягом тижня.', NULL, 260, 1791842681289, 1791842681289),
('Часті питання', 'Роздатка й друк', 'msg', '«Що друкувати?»', '', '', 'Роздатка — PDF на А4: для 1–4 класу є паспорт мандрівника, аркуші-завдання, ляльки-розмальовки, наліпки, закладки й грамота; для 5–7 і 8–11 — аркуші з текстами, питаннями й есе. Друкується і в кольорі, і чорно-білою. Відповіді для вчителя є в кінці.', NULL, 270, 1791842681289, 1791842681289),
('Часті питання', 'Чи можна провести у кількох своїх класах?', 'msg', 'Один учитель хоче використати набір у кількох класах.', '', '', 'Так, можна використовувати набір у кількох своїх класах 🙂 Код працює на 3 ваших пристроях, а в застосунку можна обирати версії для різного віку.', NULL, 280, 1791842681289, 1791842681289),
('Часті питання', 'Чи можна з колегами', 'msg', '«Можна поділитися з колегою?»', '', '', 'Код особистий і працює на 3 ваших пристроях. Для колеги краще окремий код — тоді в колеги буде власний доступ на 3 пристрої 🙂 Якщо вас кілька з однієї школи, напишіть, домовимося.', NULL, 290, 1791842681289, 1791842681289),
('Часті питання', 'Чи будуть інші набори', 'msg', '«А що ще у вас є?»', '', '', 'Зараз готуємо наступні набори до інших свят 🙂 Щойно вийдуть, повідомимо — стежте за нашою сторінкою, або я напишу вам сюди.', NULL, 300, 1791842681289, 1791842681289),
('Часті питання', 'Звідки факти', 'msg', '«А це правдиво?» / «Це ШІ?»', '', '', 'Усі факти перевірені за джерелами: укази, авторські тексти творів, музейні колекції, академічні енциклопедії. У застосунку є розділ «Джерела й фактчек» — біля кожного посилання написано, що саме воно підтверджує. Мультфільми позначені як «художня реконструкція».', NULL, 310, 1791842681289, 1791842681289),
('Проблеми з доступом', 'Код не підходить', 'msg', '«Пише, що такого коду немає».', '', '', '{hi}, перевірте, будь ласка, код ще раз: {code}. У кодах немає літер O, I, L і цифр 0, 1 — їх легко сплутати. Найпростіше скопіювати код із повідомлення й вставити. Якщо не вийде — надішліть скриншот, розберемося 🙂', NULL, 320, 1791842681289, 1791842681289),
('Проблеми з доступом', 'Ліміт пристроїв', 'msg', '«Пише, що код уже на максимумі пристроїв».', '', '', '{hi}, код уже активовано на 3 пристроях. На тому, яким більше не користуєтесь, натисніть іконку людини вгорі → «Вийти з цього пристрою», і місце звільниться. Якщо того пристрою вже немає під рукою — напишіть, я звільню місце 🙂', NULL, 330, 1791842681289, 1791842681289),
('Проблеми з доступом', 'Знову просить код', 'msg', 'Застосунок попросив код ще раз.', '', '', 'Так буває раз на місяць або після очищення браузера — просто введіть той самий код: {code}. Це не додає новий пристрій, якщо ви на тому самому 🙂', NULL, 340, 1791842681289, 1791842681289),
('Проблеми з доступом', 'Не йде відео', 'msg', 'Мультфільм не запускається.', '', '', '{hi}, спробуйте, будь ласка:
1. Оновити сторінку.
2. Відкрити в Chrome або Edge (на деяких шкільних дошках старий браузер).
3. Якщо інтернет слабкий — удома натисніть «Робота без інтернету → Зберегти», і в школі відео піде з пам''яті пристрою.
Якщо не допоможе, надішліть скриншот і напишіть, на якому пристрої відкриваєте.', NULL, 350, 1791842681289, 1791842681289),
('Проблеми з доступом', 'Не прийшов лист', 'msg', '«Лист із кодом не прийшов».', '', '', '{hi}, перевірте, будь ласка, папки «Спам» і «Реклама» — лист міг потрапити туди. Про всяк випадок ось ваш код: {code}

{howto}', NULL, 360, 1791842681289, 1791842681289),
('Проблеми з доступом', 'Загубився код', 'msg', 'Людина не може знайти повідомлення або лист із кодом.', '', '', 'Звісно, допоможу 🙂 Напишіть, будь ласка, ім''я та прізвище або електронну пошту, які вказували під час покупки. Я знайду ваше замовлення та повторно надішлю код.', NULL, 370, 1791842681289, 1791842681289),
('Проблеми з доступом', 'Не знаходить вибір класу', 'msg', '«А де 5–7 клас?»', '', '', 'Відкрийте набір «Машина часу рідної мови» — під назвою є рядок «Клас: 1–4 · 5–7 · 8–11». Натисніть свій, і завдання, сценарій та роздатка зміняться. Прогрес у кожного класу свій.', NULL, 380, 1791842681289, 1791842681289),
('Нагадування', 'Ціна для перших покупців — до 19 жовтня', 'msg', 'Усім, хто питав і замовк. Актуально до 19 жовтня включно.', 'Додайте одну картку use-v-odnomu-nabori.jpg. Не додавайте демо, посилання чи інші зображення.', '', 'Добрий день 😊 Ви цікавилися готовим уроком «Машина часу рідної мови».

Щоб було наочно, залишаю картку з усім, що входить у набір 👇

Увесь комплект зараз коштує 250 ₴, доступ залишається назавжди. Стартова ціна діє до 19 жовтня включно, з 20 жовтня буде 300 ₴.

Якщо актуально, напишіть «ОФОРМИТИ», і я одразу надішлю реквізити. Без додаткових форм і реєстрації 💛', 1792443600000, 390, 1791842681289, 1791842681289),
('Нагадування', 'Після демо мовчить', 'msg', 'Через 1–2 дні після «Хочу демо».', '', '', '{hi} 😊 Вдалося подивитися демо з Тарасом Шевченком? Якщо урок ще актуальний, напишіть, для якого класу готуєтеся, і я підкажу щодо матеріалів.', NULL, 400, 1791842681289, 1791842681289),
('Нагадування', 'Оплата наступного тижня', 'msg', 'Людина чекає зарплату або просить повернутися пізніше.', '', '', 'Так, звісно 😊 Наступного тижня можна. До 19 жовтня включно діє ціна 250 ₴ за весь набір, тож ви встигнете. Якщо не заперечуєте, наступного тижня я коротко нагадаю вам у цьому чаті 💛', 1792443600000, 410, 1791842681289, 1791842681289),
('Нагадування', 'Нагадування у домовлений день', 'msg', 'Надішліть у день, коли людина просила нагадати.', '', '', 'Добрий день 😊 Як і домовлялися, нагадую про «Машину часу рідної мови». Якщо готові оформити, напишіть «ОФОРМИТИ», і я одразу надішлю реквізити 💛', NULL, 420, 1791842681289, 1791842681289),
('Нагадування', 'Останній день ціни 250 ₴', 'msg', 'Лише 19 жовтня тим, хто вже цікавився. Після цього більше не нагадувати.', '', '', 'Добрий день 😊 Коротко нагадую: сьогодні останній день, коли «Машина часу рідної мови» коштує 250 ₴. З 20 жовтня ціна буде 300 ₴.

Якщо хочете оформити за стартовою ціною, напишіть «ОФОРМИТИ», і я одразу надішлю реквізити 💛', 1792443600000, 430, 1791842681289, 1791842681289),
('Нагадування', 'За тиждень до свята', 'msg', 'Близько 20 жовтня тим, хто цікавився.', '', '', '{hi} 😊 До Дня української писемності та мови залишився тиждень. Урок «Машина часу рідної мови» вже готовий для 1–11 класів: мультфільми, завдання для дошки, роздатка й сценарій. Ціна — {price}, доступ назавжди.

